const barColor = ["ok", "warn", "bad", "ok", "warn", "bad"]

function svg(v) {
  const chip = (x, y, c, label) => `
    <rect x="${x}" y="${y}" width="26" height="26" rx="3" fill="${c}"/>
    <text x="${x + 38}" y="${y + 20}" font-family="sans-serif" font-size="24" fill="#1a1a1a">${label}</text>`
  const stat = (x, n, label, c) => `
    <text x="${x}" y="230" font-family="sans-serif" font-size="64" font-weight="300" fill="#111">${n}</text>
