    <rect x="${x}" y="284" width="180" height="4" fill="${c}"/>`
  const barsSvg = bars.map((f, i) => {
    const bh = Math.round(f * 130)
    const x = 40 + i * 186
    return `
    <rect x="${x}" y="${470 - bh}" width="120" height="${bh}" fill="${v[barColor[i]]}"/>
