  ${chip(120, 98, v.ok, "正常")}
  ${chip(320, 98, v.warn, "警告")}
  ${chip(520, 98, v.bad, "严重")}
  ${stat(40, 12, "检查项", v.ok)}
  ${stat(420, 5, "警告项", v.warn)}
  ${stat(800, 3, "严重项", v.bad)}
  <line x1="0" y1="310" x2="${W}" y2="310" stroke="#e2e2e2"/>
  <text x="40" y="345" font-family="sans-serif" font-size="24" fill="#555">各步骤问题数</text>
  ${barsSvg}
  <text x="${W - 40}" y="${H - 16}" text-anchor="end" font-family="sans-serif" font-size="22" fill="#666">${v.note}</text>
</svg>
`}

fs.mkdirSync("assets", { recursive: true })
for (const v of views) fs.writeFileSync(`assets/${v.file}`, svg(v))
console.log("wrote", views.map((v) => v.file).join(", "))
EOF
